# ---------------------------------------------------------------------------
# Contract: Export Shape
# ---------------------------------------------------------------------------

class TestExportContract:
    """Validate the top-level structure of the exported configuration."""

    def test_export_is_object(self, config):
        """The export must be a plain dictionary."""
        assert isinstance(config, dict), (
            f"Expected dict export, got {type(config).__name__}"
        )

    def test_export_has_plugins_key(self, config):
        """The `plugins` key must be present."""
        assert "plugins" in config, "Missing 'plugins' key in export."

    def test_plugins_is_object(self, config):
        """The `plugins` value must be a dictionary."""
        assert isinstance(config["plugins"], dict), (
            f"Expected dict for 'plugins', got {type(config['plugins']).__name__}"
        )

    def test_no_unknown_top_level_keys(self, config):
        """Only `plugins` is permitted at the top level."""
        allowed = {"plugins"}
        unknown = set(config.keys()) - allowed
        assert not unknown, f"Unexpected top-level keys: {unknown}"


# ---------------------------------------------------------------------------
# Plugin Registration
# ---------------------------------------------------------------------------

class TestPluginRegistration:
    """Validate the registered PostCSS plugins."""

    @pytest.mark.parametrize(
        "plugin_name",
        ["tailwindcss", "autoprefixer"],
        ids=["tailwindcss", "autoprefixer"],
    )
    def test_required_plugin_present(self, config, plugin_name):
        """Each required plugin must be registered."""
        plugins = config["plugins"]
        assert plugin_name in plugins, f"Missing required plugin: {plugin_name}"

    @pytest.mark.parametrize(
        "plugin_name",
        ["tailwindcss", "autoprefixer"],
        ids=["tailwindcss", "autoprefixer"],
    )
    def test_required_plugin_not_null(self, config, plugin_name):
        """Registered plugins must not be null/undefined."""
        plugins = config["plugins"]
        assert plugins[plugin_name] is not None, (
            f"Plugin '{plugin_name}' is null."
        )

    def test_no_unknown_plugins(self, config):
        """No unapproved plugins should be registered."""
        allowed = {"tailwindcss", "autoprefixer"}
        unknown = set(config["plugins"].keys()) - allowed
        assert not unknown, f"Unexpected plugins registered: {unknown}"

    def test_plugin_count_exact(self, config):
        """Exactly two plugins must be registered."""
        assert len(config["plugins"]) == 2, (
            f"Expected 2 plugins, got {len(config['plugins'])}"
        )


# ---------------------------------------------------------------------------
# Serialization & Determinism
# ---------------------------------------------------------------------------

class TestSerialization:
    """Ensure the config is JSON-serializable for build tools."""

    def test_json_serializable(self, config):
        """Config must survive a JSON round-trip."""
        try:
            serialized = json.dumps(config)
            deserialized = json.loads(serialized)
        except (TypeError, ValueError) as exc:
            pytest.fail(f"Config is not JSON-serializable: {exc}")

        assert deserialized == config, "JSON round-trip altered the config."

    def test_plugin_options_serializable(self, config):
        """Each plugin's option object must be JSON-safe."""
        for plugin_name, options in config["plugins"].items():
            try:
                json.dumps(options)
            except (TypeError, ValueError) as exc:
                pytest.fail(
                    f"Plugin '{plugin_name}' options are not JSON-safe: {exc}"
                )


class TestDeterminism:
    """Config must be stable across multiple loads."""

    def test_repeated_loads_identical(self, config_module):
        """Reloading the module must yield the same configuration."""
        import importlib.util

        first_export = config_module.exports

        # Reload from source
        spec = importlib.util.spec_from_file_location(
            "postcss_config_reload", CONFIG_PATH
        )
        reloaded = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(reloaded)

        assert reloaded.exports == first_export, (
            "Config is non-deterministic across loads."
        )


