class TestEnvironmentResilience:
    """Config must not depend on ambient environment variables."""

    def test_no_environment_dependency(self, monkeypatch):
        """Loading config with empty environment must succeed."""
        monkeypatch.delenv("NODE_ENV", raising=False)
        monkeypatch.delenv("TAILWIND_MODE", raising=False)

        import importlib.util

        spec = importlib.util.spec_from_file_location(
            "postcss_config_env", CONFIG_PATH
        )
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

        assert isinstance(module.exports, dict)
        assert "plugins" in module.exports


